sys_script_include.script:
var Device_Details = Class.create();
Device_Details.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getDetails:function(){
        var gr=new GlideRecordSecure("x_1916809_ai_for_0_ai_devices");
		var deviceID=this.getParameter("sysparm_getDeviceId");
		var data={};
		if(gr.get(deviceID)){
		data.model=gr.getValue("model_number");
		data.price=gr.getValue("u_price_1");
		data.description=gr.getValue("short_description");
		data.warranty=gr.getValue("warranty_expiration");
		}
		return JSON.stringify(data);
	},
    type: 'Device_Detals'
});
